CREATE TABLE departments (dept_id INTEGER, dept_name TEXT);
CREATE TABLE employees (emp_id INTEGER, dept_id INTEGER, emp_name TEXT);
INSERT INTO departments VALUES (1, 'Sales'), (2, 'HR'), (3, 'Tech');
INSERT INTO employees VALUES (101, 1, 'Alice'), (102, 1, 'Bob'), (103, 3, 'Charlie');
SELECT dept_name FROM departments d WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.dept_id) ORDER BY dept_name;
